class InsertarTexto(Command):
    def __init__(self, documento, texto):
        self.doc = documento
        self.texto = texto
        self.pos = len(documento.texto)
    def execute(self):
        self.doc.texto += self.texto
    def undo(self):
        self.doc.texto = self.doc.texto[:self.pos]

class QueryBuilder:
    def __init__(self):
        self._tabla = None
        self._campos = []
        self._where = None
    def de(self, tabla):
        self._tabla = tabla
        return self
    def seleccionar(self, *campos):
        self._campos = list(campos)
        return self
    def donde(self, condicion):
        self._where = condicion
        return self
    def construir(self):
        sql = f"SELECT {','.join(self._campos)} FROM {self._tabla}"
        if self._where: sql += f" WHERE {self._where}"
        return sql

