# Ray tracing simplificado
def trace_ray(origin, direction, scene):
    hit = scene.intersect(origin, direction)
    if hit is None:
        return background_color

    # Calcular iluminación
    color = hit.material.color * hit.material.ambient
    for light in scene.lights:
        if not in_shadow(hit.point, light):
            color += hit.material.diffuse * light.intensity

    # Reflexión
    if hit.material.reflectivity > 0:
        reflected = reflect(direction, hit.normal)
        color += trace_ray(hit.point, reflected, scene) * hit.material.reflectivity

    return color

