# Factory Method
class Notification(ABC):
    @abstractmethod
    def send(self, msg): pass

class EmailNotification(Notification):
    def send(self, msg): print(f'Email: {msg}')

class SMSNotification(Notification):
    def send(self, msg): print(f'SMS: {msg}')

class PushNotification(Notification):
    def send(self, msg): print(f'Push: {msg}')

class NotificationFactory:
    @staticmethod
    def create(type_: str) -> Notification:
        factories = {
            'email': EmailNotification,
            'sms': SMSNotification,
            'push': PushNotification,
        }
        return factories[type_]()

# Uso
notif = NotificationFactory.create('email')
notif.send('Hola')  # Email: Hola
